      {"q":"المريخ مقارنة بالأرض:","options":["أكبر منها بقليل","أكبر منها بكثير","أصغر، قطره نحو نصف قطرها","بالحجم نفسه تمامًا"],"answer":2,"explain":"قطر المريخ نحو 6800 كم، أي قرابة نصف قطر الأرض."},
      {"q":"سنة المريخ مقارنة بسنة الأرض:","options":["أطول","نصفها","مساوية لها","أقصر"],"answer":0,"explain":"المريخ أبعد عن الشمس من الأرض، فيحتاج إلى نحو 687 يومًا أرضيًا ليكمل دورته حولها."},
      {"q":"ماذا يُسمّى الروبوت ذو العجلات الذي يستكشف سطح كوكب؟","options":["صاروخ","مركبة جوالة","قمر اصطناعي","منظار"],"answer":1,"explain":"المركبات الجوالة مثل كيوريوسيتي وبرسيفيرانس تتنقل على سطح المريخ وتفحص صخوره وتربته."},
      {"q":"هل يوجد على المريخ هواء صالح للتنفس؟","options":["نعم، في الصباح فقط","نعم، مثل الأرض","نعم، في الوديان فقط","لا، غلافه رقيق ومعظمه ثاني أكسيد الكربون"],"answer":3,"explain":"الغلاف الجوي للمريخ رقيق جدًا ونحو 95% منه ثاني أكسيد الكربون، فيحتاج الرواد إلى أجهزة تنفس."},
      {"q":"ما الظاهرة الجوية الشهيرة على المريخ؟","options":["ثلوج دائمة في كل مكان","أعاصير بحرية","عواصف غبارية ضخمة","أمطار غزيرة"],"answer":2,"explain":"تهب على المريخ عواصف غبارية قد تكبر أحيانًا حتى تغطي الكوكب كله تقريبًا لأسابيع."},
      {"q":"ما الكويكبات؟","options":["أجرام صخرية صغيرة تدور حول الشمس","سحب من الغاز","نجوم صغيرة","أقمار للأرض"],"answer":0,"explain":"الكويكبات أجرام صخرية أو معدنية أصغر من الكواكب، ويوجد معظمها في حزام بين المريخ والمشتري."},
      {"q":"جاذبية المريخ أضعف من جاذبية الأرض، فلو قفزت هناك لارتفعت:","options":["الارتفاع نفسه","لن تستطيع القفز أبدًا","أقل مما على الأرض","أعلى بنحو مرتين ونصف"],"answer":3,"explain":"جاذبية المريخ نحو 38% من جاذبية الأرض، فيشدّك نحو الأسفل بقوة أقل وترتفع قفزتك أكثر.","fun":true},
      {"q":"المريخ في المتوسط:","options":["أحر من الزهرة","أحر من الأرض","أبرد من الأرض","بحرارة الأرض نفسها"],"answer":2,"explain":"متوسط حرارة المريخ نحو −65 °س، لأنه أبعد عن الشمس وغلافه الجوي رقيق لا يحفظ الحرارة."},
      {"q":"لماذا يُلقَّب المريخ بالكوكب الأحمر؟","options":["لأن تربته فيها أكسيد الحديد (الصدأ)","لأنه أقرب كوكب إلى الشمس","لأن الحمم تغطي سطحه","لأنه أسخن الكواكب"],"answer":0,"explain":"تحتوي تربة المريخ وغباره على أكاسيد الحديد، وهي المادة نفسها التي تكوّن الصدأ فتمنحه لونه الأحمر."},
      {"q":"أين يقع حزام الكويكبات؟","options":["بين زحل وأورانوس","بين الأرض والمريخ","بين المريخ والمشتري","حول قمر الأرض"],"answer":2,"explain":"يقع حزام الكويكبات بين مداري المريخ والمشتري، ويضم أعدادًا هائلة من الأجرام الصخرية."},
      {"q":"هل هبط إنسان على سطح المريخ حتى الآن؟","options":["نعم، عام 1969","نعم، عام 2000","نعم، عام 2021","لا، أُرسلت إليه روبوتات فقط"],"answer":3,"explain":"لم يصل أي إنسان إلى المريخ بعد، لكن مركبات آلية كثيرة هبطت عليه أو تدور حوله لاستكشافه."},
      {"q":"ما الجرم الوحيد غير الأرض الذي مشى عليه الإنسان؟","options":["عطارد","الزهرة","المريخ","القمر"],"answer":3,"explain":"في عام 1969 مشى رواد مهمة أبولو 11 على سطح القمر، وتلتها رحلات أخرى حتى عام 1972."},
      {"q":"الأرض والمريخ كلاهما من الكواكب:","options":["الغازية","القزمة","الصخرية","الجليدية"],"answer":2,"explain":"المريخ والأرض من الكواكب الداخلية الصخرية، لكل منهما سطح صلب من الصخور، والمريخ أصغر من الأرض."},
      {"q":"كم قمرًا يدور حول المريخ؟","options":["قمر واحد كبير","قمران صغيران","أكثر من 50 قمرًا","لا أقمار له"],"answer":1,"explain":"للمريخ قمران صغيران غير منتظمي الشكل، وكلاهما أصغر بكثير من قمر الأرض."},
      {"q":"هل عثر العلماء على حياة على المريخ؟","options":["لا، لا يوجد دليل مؤكد حتى الآن","نعم، نباتات خضراء","نعم، كائنات ذكية","نعم، حيوانات صغيرة"],"answer":0,"explain":"لم يُعثر حتى الآن على دليل مؤكد على حياة في المريخ، وما زالت المركبات تبحث عن آثار حياة ميكروبية قديمة."},
      {"q":"أعلى بركان معروف في النظام الشمسي يوجد على:","options":["عطارد","المريخ","الأرض","القمر"],"answer":1,"explain":"يرتفع بركان أوليمبوس مونس على المريخ نحو 25 كم، أي قرابة ثلاثة أضعاف ارتفاع جبل إيفرست!","fun":true},
      {"q":"ما لون الغروب على المريخ كما صوّرته المركبات الجوالة؟","options":["أحمر قانٍ","مائل إلى الأزرق","بنفسجي","أخضر"],"answer":1,"explain":"غبار المريخ الناعم يجعل الضوء الأزرق يتجمع حول الشمس عند الغروب، فتبدو السماء حولها زرقاء.","fun":true},
      {"q":"طول اليوم على المريخ:","options":["نحو أسبوع","نحو 10 ساعات فقط","يساوي سنة كاملة","قريب جدًا من يوم الأرض"],"answer":3,"explain":"يدور المريخ حول محوره في نحو 24 ساعة و37 دقيقة، فيومه أطول قليلًا من يومنا.","fun":true},
      {"q":"يشبه سطح المريخ في كثير من مناطقه:","options":["غابة استوائية","صحراء صخرية مغبرة","مدينة كبيرة","محيطًا واسعًا"],"answer":1,"explain":"سطح المريخ جاف بارد، تغطيه صخور وكثبان من الغبار الأحمر، فيشبه صحراء باردة."}
