      {"q":"ما أول كوكب اكتُشف باستخدام التلسكوب؟","options":["زحل","المريخ","أورانوس","المشتري"],"answer":2,"explain":"الكواكب من عطارد إلى زحل تُرى بالعين المجردة منذ القدم، أما أورانوس فكان أول كوكب يُكتشف بالتلسكوب."},
      {"q":"هل لأورانوس حلقات؟","options":["نعم، حلقات رقيقة داكنة","لا، أبدًا","نعم، أكبر من حلقات زحل","حلقة واحدة من الماء السائل"],"answer":0,"explain":"لأورانوس 13 حلقة معروفة، وهي رقيقة وداكنة، ولذلك لم تُكتشف إلا عام 1977."},
      {"q":"تحمل معظم أقمار أورانوس أسماء شخصيات من:","options":["أسماء علماء الفلك","مسرحيات شكسبير وأشعار بوب","أسماء مدن أوروبية","أسماء الأنهار"],"answer":1,"explain":"من أقمار أورانوس تيتانيا وأوبيرون وميراندا، وهي أسماء شخصيات أدبية من أعمال شكسبير وألكسندر بوب.","fun":true},
      {"q":"ما ترتيب أورانوس بين الكواكب من حيث البعد عن الشمس؟","options":["الخامس","السادس","الثامن","السابع"],"answer":3,"explain":"أورانوس الكوكب السابع من الشمس، ويقع بين زحل ونبتون."},
      {"q":"يصل ضوء الشمس إلى الأرض في نحو 8 دقائق، وأورانوس أبعد بنحو 19 مرة. فيصله ضوء الشمس في نحو:","options":["8 دقائق","19 دقيقة","2.5 ساعة","19 يومًا"],"answer":2,"explain":"19 × 8 ≈ 150 دقيقة ≈ 2.5 ساعة (والقيمة الأدق نحو 2.7 ساعة)."},
      {"q":"من أول رائد فضاء عربي مسلم صعد إلى الفضاء عام 1985؟","options":["علي القرني","نيل أرمسترونغ","الأمير سلطان بن سلمان","يوري غاغارين"],"answer":2,"explain":"شارك الأمير سلطان بن سلمان في رحلة المكوك ديسكفري عام 1985، فكان أول رائد فضاء سعودي وعربي مسلم."},
      {"q":"ما شكل مدار أورانوس حول الشمس؟","options":["مربع","إهليلجي قريب من الدائرة","خط مستقيم","حلزوني نحو الشمس"],"answer":1,"explain":"مدارات الكواكب كلها إهليلجية (بيضاوية)، ومدار أورانوس قريب جدًا من الدائرة."},
      {"q":"ما أول قمر اصطناعي أطلقه الإنسان إلى الفضاء عام 1957؟","options":["سبوتنيك 1","هابل","فوياجر 1","أبولو 11"],"answer":0,"explain":"أطلق الاتحاد السوفيتي سبوتنيك 1 في أكتوبر 1957، فبدأ عصر الفضاء."},
      {"q":"النجوم ذات اللون الأزرق مقارنة بالنجوم الحمراء:","options":["أبرد منها","بالحرارة نفسها","ليست نجومًا حقيقية","أسخن منها"],"answer":3,"explain":"يدل لون النجم على حرارة سطحه؛ فالنجوم الزرقاء أسخنها والحمراء أبردها، والشمس الصفراء بينهما."},
      {"q":"يتكون الغلاف الجوي لأورانوس أساسًا من:","options":["الميثان فقط","الهيدروجين والهيليوم","ثاني أكسيد الكربون","النيتروجين والأكسجين"],"answer":1,"explain":"الهيدروجين والهيليوم يشكلان معظم غلاف أورانوس، أما الميثان فنسبته صغيرة لكنه يمنح الكوكب لونه."},
      {"q":"ما أكبر أقمار أورانوس؟","options":["تيتانيا","تيتان","فوبوس","غانيميد"],"answer":0,"explain":"تيتانيا أكبر أقمار أورانوس، يليه أوبيرون، وقد اكتشفهما هيرشل نفسه عام 1787."},
      {"q":"لماذا تبدو بعض النجوم أسطع من غيرها في السماء؟","options":["لأنها كواكب","لأنها أقرب إلى القمر","لأنها تعكس ضوء الشمس","لاختلاف حجمها وحرارتها وبعدها عنا"],"answer":3,"explain":"النجم الكبير الحار يبدو ساطعًا، والنجم القريب منا يبدو أسطع من نجم مثله بعيد."},
      {"q":"أي كوكب سُجّلت فيه أبرد درجة حرارة في غلافه الجوي (نحو −224 °س)؟","options":["نبتون","أورانوس","عطارد","المريخ"],"answer":1,"explain":"مع أن نبتون أبعد، فإن أورانوس هو صاحب أبرد غلاف جوي، لأن حرارته الداخلية ضئيلة جدًا!","fun":true},
      {"q":"يبعد أورانوس نحو 19 وحدة فلكية، والوحدة الفلكية نحو 150 مليون كم، فبعده نحو:","options":["290 مليون كم","2.9 مليار كم","150 مليون كم","29 مليار كم"],"answer":1,"explain":"19 × 150 مليون ≈ 2850 مليون كم، أي نحو 2.9 مليار كم من الشمس."}
